n = int(input())
for i in range(n):
    score = int(input())
    if score < 0 or score > 100:
        grade = "Invalid"
    elif score >= 85:
        grade = "A"
    elif score >= 70:
        grade = "B"
    elif score >= 50:
        grade = "C"
    elif score >= 40:
        grade = "Retake"
    else:
        grade = "Fail"
    print(f"{score}: {grade}")

a = int(input())
b = int(input())

if a <= b:
    step = 1
else:
    step = -1

for i in range(a, b + step, step):
    if i % 3 == 0 and i % 5 == 0:
        print("ClapStomp")
    elif i % 3 == 0:
        print("Clap")
    elif i % 5 == 0:
        print("Stomp")
    else:
        print(i)
